from typing import List

def sort_numbers(numbers: str) -> str:
    valid_numbers = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    words = numbers.split()

    for word in words:
        if word not in valid_numbers:
            raise ValueError(f"Invalid input: {word} is not a valid number word.")

    sorted_words = sorted(words, key=lambda x: valid_numbers.index(x))
    return ' '.join(sorted_words)

