    // Helper function to check if the output is a sorted version of input
    function IsSortedOutput(output: string, input: string) : bool
        reads {}
    {
        var inputWords := Split(input, " ");
        var outputWords := Split(output, " ");
        // Check the output contains the same words as the input
        inputWords.Length == outputWords.Length && 
        forall i :: 0 <= i < outputWords.Length ==> outputWords[i] in inputWords &&
        IsSorted(outputWords)
    }

    // Helper function to check if a list of strings is sorted
    function IsSorted(words: seq<string>) : bool
        reads {}
    {
        forall i :: 0 <= i < words.Length - 1 ==> words[i] <= words[i + 1]
